const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = (ip: string) => ({ ip });
const conecta = (ip: string, port: number, clientPort?: number) =>
  aws.network.canConnect(vpc, { from: visitante(ip), to: web, protocol: "tcp", port, clientPort });
const resultado = conecta("192.0.2.10", 22);
assert.strictEqual(resultado.allowed, true, resultado.reason);

const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = (ip: string) => ({ ip });
const conecta = (ip: string, port: number, clientPort?: number) =>
  aws.network.canConnect(vpc, { from: visitante(ip), to: web, protocol: "tcp", port, clientPort });
const casos: [string, number][] = [
  ["198.51.100.7", 22],
  ["203.0.113.50", 22],
  ["198.51.100.7", 3306],
  ["198.51.100.7", 3389],
  ["198.51.100.7", 8080],
];
for (const [ip, port] of casos) {
  assert.strictEqual(conecta(ip, port).allowed, false, ip + " hacia el puerto " + port + " debe seguir bloqueado");
}
const udp = aws.network.canConnect(vpc, { from: visitante("198.51.100.7"), to: web, protocol: "udp", port: 443 });
assert.strictEqual(udp.allowed, false, "UDP 443 no está publicado");

const grupo = vpc.securityGroups[0];
const flujo = (peer: string, port: number) => ({ direction: "inbound" as const, protocol: "tcp" as const, port, peer });
assert.strictEqual(aws.network.securityGroupAllows(grupo.rules, flujo("198.51.100.7", 22)), false);
assert.strictEqual(aws.network.securityGroupAllows(grupo.rules, flujo("198.51.100.7", 443)), true);
assert.strictEqual(aws.network.securityGroupAllows(grupo.rules, flujo("192.0.2.10", 22)), true);

const reglas = vpc.subnets[0].nacl;
const salida = (port: number) => aws.network.naclAllows(reglas, { direction: "outbound", protocol: "tcp", port, peer: "198.51.100.7" }).allowed;
const entrada = (port: number) => aws.network.naclAllows(reglas, { direction: "inbound", protocol: "tcp", port, peer: "198.51.100.7" }).allowed;
assert.strictEqual(salida(49152), true, "la respuesta por el puerto 49152 debe poder salir");
for (const port of [22, 23, 25]) {
  assert.strictEqual(salida(port), false, "la NACL no debe permitir salida por el puerto " + port);
}
assert.strictEqual(entrada(443), true);
assert.strictEqual(entrada(22), false);
assert.strictEqual(entrada(3306), false);

